import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"百度网盘新版API","description":"突然发现百度网盘又更新 API 了....明明 UI 一点都没有更新.我严重怀疑这个前端工程师是有多寂寞...\\n没事就更新 JS...这已经是我观察发现的第三次更新了...每次都导致我的 aria2c 导出脚本失效...","frontmatter":{"title":"百度网盘新版API","date":"2014-07-02 14:09","comments":true,"archives":2014,"tags":["baidu"]},"headers":[],"relativePath":"posts/2014-07-02-baidu-pan/index.md","filePath":"posts/2014/2014-07-02-baidu-pan.md"}'),p={name:"posts/2014-07-02-baidu-pan/index.md"};function o(t,s,r,c,i,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>突然发现百度网盘又更新 API 了....明明 UI 一点都没有更新.我严重怀疑这个前端工程师是有多寂寞... 没事就更新 JS...这已经是我观察发现的第三次更新了...每次都导致我的 aria2c 导出脚本失效...</p><p>于是我又苦苦寻找新版的 JS 到底是怎么实现下载的,虽说可以直接操纵 DOM 获取选中的文件的 fs_id 信息 然后 POST 数据获取 dlink(下载地址),但是这样怎么也不够优雅啊...因为百度自己的 JS 肯定实现了这部分内容 于是我便花了更多的时间找 API,但是百度那既压缩又混淆的 JS 代码真是读起来特带劲啊(我绝对不是抖 M)</p><p>于是说一下百度的新版 API 吧:</p><h2 id="toast-模块" tabindex="-1">Toast 模块 <a class="header-anchor" href="#toast-模块" aria-label="Permalink to &quot;Toast 模块&quot;">​</a></h2><p>新版 API 把每个功能全部模块化,声明某个模块的方法是使用 require 方法.</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#6F42C1;"> SetMessage</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> function</span><span style="color:#24292E;"> (</span><span style="color:#E36209;">msg</span><span style="color:#24292E;">, </span><span style="color:#E36209;">type</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  var</span><span style="color:#24292E;"> Toast </span><span style="color:#D73A49;">=</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;common:widget/toast/toast.js&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">  Toast.obtain.</span><span style="color:#6F42C1;">useToast</span><span style="color:#24292E;">({</span></span>
<span class="line"><span style="color:#24292E;">    toastMode: Toast.obtain[type],</span></span>
<span class="line"><span style="color:#24292E;">    msg: msg,</span></span>
<span class="line"><span style="color:#24292E;">    sticky: </span><span style="color:#005CC5;">false</span></span>
<span class="line"><span style="color:#24292E;">  });</span></span>
<span class="line"><span style="color:#24292E;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>于是我便封装了一个函数用来实现消息提示.</p><h2 id="data-center-模块" tabindex="-1">data-center 模块 <a class="header-anchor" href="#data-center-模块" aria-label="Permalink to &quot;data-center 模块&quot;">​</a></h2><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> File </span><span style="color:#D73A49;">=</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;common:widget/data-center/data-center.js&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">return</span><span style="color:#24292E;"> File.</span><span style="color:#6F42C1;">get</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;selectedList&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>data-center 模块可以获取选择的文件的 fs_id,通过传入 fs_id 可以获取 dlink. File.get(&quot;selectedItemList&quot;)可以获取选择的文件的 DOM 结构.</p><h2 id="commonservice-模块" tabindex="-1">commonService 模块 <a class="header-anchor" href="#commonservice-模块" aria-label="Permalink to &quot;commonService 模块&quot;">​</a></h2><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> Service </span><span style="color:#D73A49;">=</span><span style="color:#6F42C1;"> require</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;common:widget/commonService/commonService.js&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">Service.</span><span style="color:#6F42C1;">getDlink</span><span style="color:#24292E;">(</span></span>
<span class="line"><span style="color:#005CC5;">  JSON</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">stringify</span><span style="color:#24292E;">(File.</span><span style="color:#6F42C1;">get</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;selectedList&#39;</span><span style="color:#24292E;">)),</span></span>
<span class="line"><span style="color:#032F62;">  &#39;dlink&#39;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  self.aria2_rpc.</span><span style="color:#6F42C1;">bind</span><span style="color:#24292E;">(self)</span></span>
<span class="line"><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>commonService 模块有很多实用的功能,但是我们目前只需要这么一个就足够了,有需要的可以自己研究下.getDlink 接受三个参数.第一个是 每个要下载的文件的 fs_id,多个文件是数组的字符串方式传入,第二个是获取 dlink 的类型,总共有三个类型 batsh,dlink,nolimit,第一个类型 是把传入的多个文件合并成一个压缩包进行下载,返回一个 dlink,第二个是单独获取每个文件的 dlink,第三个还没有尝试过.第三个参数是回调函数 会传入 POST 之后获取的 json 数据.</p><h2 id="设置-ua" tabindex="-1">设置 UA <a class="header-anchor" href="#设置-ua" aria-label="Permalink to &quot;设置 UA&quot;">​</a></h2><p>因为我现在还没找到怎么获取选择的文件名的列表,所以在 aria2c 的时候无法手动指定文件名.貌似不写 UA 的情况下会被限速. 设置 chrome 的 UA 文件名会被 encode,所以 aria2c 的时候设置 UA 为百度云管家的 UA</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#005CC5;"> UA</span><span style="color:#D73A49;"> =</span><span style="color:#032F62;"> &#39;netdisk;4.4.0.6;PC;PC-Windows;6.2.9200;WindowsBaiduYunGuanJia&#39;</span><span style="color:#24292E;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="设置-cookie" tabindex="-1">设置 cookie <a class="header-anchor" href="#设置-cookie" aria-label="Permalink to &quot;设置 cookie&quot;">​</a></h2><p>百度云盘升级之后仅仅只有 dlink 还不行,还需要一个 name 为<code>BDUSS</code>的 cookie. 但是这个 cookie 被设置为 http only,所以 JS 是无论如何也获取不到的.目前只能采用手动设置的方法. 还好这个 cookie 每个用户基本都是唯一的,设置一次永久使用,否则真是麻烦.</p><p>完整版实现<a href="https://gist.github.com/acgotaku/29d1fbe3dbf777c25254" target="_blank" rel="noreferrer">GitHub</a></p>`,19)])])}const y=a(p,[["render",o]]);export{b as __pageData,y as default};
